function open(s){if(s.phase!=='prep')return false;let ids=dayGuests(s);s.phase='service';s.elapsed=0;s.nextGuest=0;s.schedule=ids.map((id,i)=>({id,at:i===0?0:14+i*15}));s.tables=Array.from({length:s.upgrades.tables?6:4},(_,i)=>({id:i,status:'empty'}));s.stats={revenue:0,tips:0,food:0,pots:0,expense:0,served:0,lost:0,pets:0,petTables:[],records:[],showHits:0,showDone:false,reward:0,startCash:s.cash,goal:false};s.closing=false;log(s,`第 ${s.day} 天开门：${event(s).name}`);seat(s);return true;}
